// Raw Win32 Bluetooth LE plumbing (SetupDi + BluetoothAPIs), generated by CsWin32.
// No Microsoft.Windows.SDK.NET.dll, no WinRT: every call here is plain P/Invoke.

using System.Runtime.InteropServices;
using System.Text;
using Microsoft.Win32.SafeHandles;
using Windows.Win32;
using Windows.Win32.Devices.Bluetooth;
using Windows.Win32.Devices.DeviceAndDriverInstallation;
using Windows.Win32.Devices.Properties;
using Windows.Win32.Foundation;
using Windows.Win32.Storage.FileSystem;

namespace BandBuzzLite.Band;

internal static class Win32Gatt
{
    /// <summary>GUID_BLUETOOTHLE_DEVICE_INTERFACE: the SetupDi class to enumerate LE devices.</summary>
    public static readonly Guid BleDeviceInterfaceClass = new("781aee18-7733-4ce4-add0-91f41c67b592");

    /// <summary>DEVPKEY_Bluetooth_DeviceAddress (string), used to match a MAC to an interface.</summary>
    private static readonly DEVPROPKEY DeviceAddressKey = new()
    {
        fmtid = new Guid("2bd67d8b-8beb-48d5-87e0-6cda3428040a"),
        pid = 1,
    };

    public sealed record BleCandidate(string DevicePath, string? AddressProp);

    // ---- address helpers ----

    /// <summary>ulong address -&gt; AA:BB:CC:DD:EE:FF (BTH_ADDR stores display order, MSB first).</summary>
    public static string ToMacString(ulong addr) =>
        $"{(addr >> 40) & 0xFF:X2}:{(addr >> 32) & 0xFF:X2}:{(addr >> 24) & 0xFF:X2}:" +
        $"{(addr >> 16) & 0xFF:X2}:{(addr >> 8) & 0xFF:X2}:{addr & 0xFF:X2}";

    /// <summary>Any MAC-ish text -&gt; 12 uppercase hex chars (tolerates ':', '-', case).</summary>
    public static string NormalizeMac(string s) =>
        string.Concat(s.Where(Uri.IsHexDigit)).ToUpperInvariant();

    // ---- radio / discovery ----

    public static bool RadioPresent()
    {
        unsafe
        {
            var prm = new BLUETOOTH_FIND_RADIO_PARAMS { dwSize = (uint)sizeof(BLUETOOTH_FIND_RADIO_PARAMS) };
            HANDLE hRadio;
            var hFind = PInvoke.BluetoothFindFirstRadio(&prm, &hRadio);
            if (hFind.Value == null)
                return false;
            PInvoke.BluetoothFindRadioClose(hFind);
            PInvoke.CloseHandle(hRadio);
            return true;
        }
    }

    public sealed record BtDevice(ulong Address, string Name, bool Remembered, bool Connected, bool Authenticated);

    private static BLUETOOTH_DEVICE_INFO NewDeviceInfo() =>
        new() { dwSize = (uint)Marshal.SizeOf<BLUETOOTH_DEVICE_INFO>() };

    /// <summary>Known (remembered/connected) devices. No inquiry: fast, never blocks.</summary>
    public static unsafe List<BtDevice> ListKnownDevices()
    {
        var out_ = new List<BtDevice>();
        var search = new BLUETOOTH_DEVICE_SEARCH_PARAMS
        {
            dwSize = (uint)sizeof(BLUETOOTH_DEVICE_SEARCH_PARAMS),
            fReturnAuthenticated = true,
            fReturnRemembered = true,
            fReturnUnknown = true,
            fReturnConnected = true,
            fIssueInquiry = false,
            cTimeoutMultiplier = 0,
            hRadio = default,
        };
        var info = NewDeviceInfo();
        var hFind = PInvoke.BluetoothFindFirstDevice(&search, &info);
        if (hFind.Value == null)
            return out_;
        try
        {
            out_.Add(ToBtDevice(info));
            while (PInvoke.BluetoothFindNextDevice(hFind, &info))
                out_.Add(ToBtDevice(info));
        }
        finally
        {
            PInvoke.BluetoothFindDeviceClose(hFind);
        }
        return out_;
    }

    private static BtDevice ToBtDevice(BLUETOOTH_DEVICE_INFO info) => new(
        info.Address.ullLong, info.szName.ToString(), info.fRemembered, info.fConnected, info.fAuthenticated);

    /// <summary>
    /// Best-effort inquiry scan for a MAC (BR/EDR inquiry; LE-only bands may not
    /// answer - the SetupDi enumeration below is the primary path).
    /// </summary>
    public static unsafe bool InquiryScanFor(ulong addr, TimeSpan budget, Action<string> log)
    {
        var search = new BLUETOOTH_DEVICE_SEARCH_PARAMS
        {
            dwSize = (uint)sizeof(BLUETOOTH_DEVICE_SEARCH_PARAMS),
            fReturnAuthenticated = true,
            fReturnRemembered = true,
            fReturnUnknown = true,
            fReturnConnected = true,
            fIssueInquiry = true,
            cTimeoutMultiplier = 12, // ~15s inquiry
            hRadio = default,
        };
        var info = NewDeviceInfo();
        var hFind = PInvoke.BluetoothFindFirstDevice(&search, &info);
        if (hFind.Value == null)
        {
            log($"inquiry failed (0x{Marshal.GetLastPInvokeError():X8}), skipping");
            return false;
        }
        try
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            if (info.Address.ullLong == addr)
                return true;
            while (sw.Elapsed < budget)
            {
                if (!PInvoke.BluetoothFindNextDevice(hFind, &info))
                    break;
                if (info.Address.ullLong == addr)
                    return true;
            }
            return false;
        }
        finally
        {
            PInvoke.BluetoothFindDeviceClose(hFind);
        }
    }

    // ---- BTHLE interface enumeration ----

    /// <summary>All present LE device interfaces with their address property (when readable).</summary>
    public static List<BleCandidate> EnumBleInterfaces()
    {
        var out_ = new List<BleCandidate>();
        var flags = SETUP_DI_GET_CLASS_DEVS_FLAGS.DIGCF_PRESENT
            | SETUP_DI_GET_CLASS_DEVS_FLAGS.DIGCF_DEVICEINTERFACE;
        var classGuid = BleDeviceInterfaceClass;
        HDEVINFO raw;
        unsafe
        {
            raw = PInvoke.SetupDiGetClassDevs(&classGuid, null, default, flags);
        }
        if (raw.Value == (nint)(-1))
            throw new InvalidOperationException(
                $"SetupDiGetClassDevs failed (0x{Marshal.GetLastPInvokeError():X8})");
        using var set = new SetupDiDestroyDeviceInfoListSafeHandle(raw.Value, ownsHandle: true);
        var guid = BleDeviceInterfaceClass;
        for (uint i = 0; i < 256; i++)
        {
            var ifData = new SP_DEVICE_INTERFACE_DATA
            {
                cbSize = (uint)Marshal.SizeOf<SP_DEVICE_INTERFACE_DATA>(),
            };
            if (!PInvoke.SetupDiEnumDeviceInterfaces(set, null, guid, i, ref ifData))
                break; // ERROR_NO_MORE_ITEMS (or a real error; lists here are short)
            var devData = new SP_DEVINFO_DATA
            {
                cbSize = (uint)Marshal.SizeOf<SP_DEVINFO_DATA>(),
            };
            string path;
            try
            {
                path = GetInterfacePath(set, ifData, ref devData);
            }
            catch
            {
                continue;
            }
            out_.Add(new BleCandidate(path, GetAddressProperty(set, devData)));
        }
        return out_;
    }

    private static string GetInterfacePath(
        SafeHandle set, SP_DEVICE_INTERFACE_DATA ifData, ref SP_DEVINFO_DATA devData)
    {
        PInvoke.SetupDiGetDeviceInterfaceDetail(set, ifData, Span<byte>.Empty, out var need, ref devData);
        if (need < 8)
            throw new InvalidOperationException("no detail size");
        var buf = new byte[need];
        if (!PInvoke.SetupDiGetDeviceInterfaceDetail(set, ifData, buf.AsSpan(), out _, ref devData))
            throw new InvalidOperationException(
                $"detail failed (0x{Marshal.GetLastPInvokeError():X8})");
        // Layout: DWORD cbSize, then null-terminated WCHAR path.
        var chars = MemoryMarshal.Cast<byte, char>(buf.AsSpan(4));
        var end = chars.IndexOf('\0');
        return new string(chars[..(end < 0 ? chars.Length : end)]);
    }

    private static string? GetAddressProperty(SafeHandle set, SP_DEVINFO_DATA devData)
    {
        try
        {
            if (!PInvoke.SetupDiGetDeviceProperty(
                    set, devData, DeviceAddressKey, out _, Span<byte>.Empty, out var need, 0)
                || need == 0 || need > 256)
                return null;
            var buf = new byte[need];
            if (!PInvoke.SetupDiGetDeviceProperty(
                    set, devData, DeviceAddressKey, out _, buf.AsSpan(), out _, 0))
                return null;
            var chars = MemoryMarshal.Cast<byte, char>(buf.AsSpan());
            var end = chars.IndexOf('\0');
            var s = new string(chars[..(end < 0 ? chars.Length : end)]);
            return string.IsNullOrWhiteSpace(s) ? null : s;
        }
        catch
        {
            return null;
        }
    }

    // ---- GATT helpers ----

    public static void ThrowIfFailed(HRESULT hr, string op)
    {
        if (hr.Failed)
            throw new InvalidOperationException($"{op} failed: {hr} (0x{hr.Value:X8})");
    }

    public const uint EMoreData = 0x800700EA; // HRESULT_FROM_WIN32(ERROR_MORE_DATA)

    public static bool UuidMatches(BTH_LE_UUID u, Guid expected)
    {
        if (u.IsShortUuid)
            return new Guid($"0000{u.Value.ShortUuid:X4}-0000-1000-8000-00805f9b34fb") == expected;
        return u.Value.LongUuid == expected;
    }

    public static SafeFileHandle OpenDevice(string path)
    {
        try
        {
            var h = PInvoke.CreateFile(
                path,
                (uint)(GENERIC_ACCESS_RIGHTS.GENERIC_READ | GENERIC_ACCESS_RIGHTS.GENERIC_WRITE),
                FILE_SHARE_MODE.FILE_SHARE_READ | FILE_SHARE_MODE.FILE_SHARE_WRITE,
                null,
                FILE_CREATION_DISPOSITION.OPEN_EXISTING,
                FILE_FLAGS_AND_ATTRIBUTES.FILE_ATTRIBUTE_NORMAL,
                null);
            if (h.IsInvalid)
                throw new InvalidOperationException(
                    $"CreateFile({path}) failed (0x{Marshal.GetLastPInvokeError():X8})");
            return h;
        }
        catch (Exception ex) when (ex is not InvalidOperationException)
        {
            throw new InvalidOperationException(
                $"CreateFile({path}) failed: {ex.Message}", ex);
        }
    }

    public static BTH_LE_GATT_SERVICE[] GetServices(SafeHandle h)
    {
        var hr = PInvoke.BluetoothGATTGetServices(
            h, Span<BTH_LE_GATT_SERVICE>.Empty, out var actual, PInvoke.BLUETOOTH_GATT_FLAG_NONE);
        if ((hr.Failed && hr.Value != unchecked((int)EMoreData)) || actual == 0)
            ThrowIfFailed(hr, "BluetoothGATTGetServices(count)");
        var buf = new BTH_LE_GATT_SERVICE[actual];
        ThrowIfFailed(PInvoke.BluetoothGATTGetServices(
            h, buf.AsSpan(), out actual, PInvoke.BLUETOOTH_GATT_FLAG_NONE), "BluetoothGATTGetServices");
        return buf.AsSpan(0, actual).ToArray();
    }

    public static BTH_LE_GATT_CHARACTERISTIC[] GetCharacteristics(SafeHandle h, BTH_LE_GATT_SERVICE svc)
    {
        var hr = PInvoke.BluetoothGATTGetCharacteristics(
            h, svc, Span<BTH_LE_GATT_CHARACTERISTIC>.Empty, out var actual, PInvoke.BLUETOOTH_GATT_FLAG_NONE);
        if ((hr.Failed && hr.Value != unchecked((int)EMoreData)) || actual == 0)
            ThrowIfFailed(hr, "BluetoothGATTGetCharacteristics(count)");
        var buf = new BTH_LE_GATT_CHARACTERISTIC[actual];
        ThrowIfFailed(PInvoke.BluetoothGATTGetCharacteristics(
            h, svc, buf.AsSpan(), out actual, PInvoke.BLUETOOTH_GATT_FLAG_NONE), "BluetoothGATTGetCharacteristics");
        return buf.AsSpan(0, actual).ToArray();
    }

    public static BTH_LE_GATT_DESCRIPTOR[] GetDescriptors(SafeHandle h, BTH_LE_GATT_CHARACTERISTIC ch)
    {
        var hr = PInvoke.BluetoothGATTGetDescriptors(
            h, ch, Span<BTH_LE_GATT_DESCRIPTOR>.Empty, out var actual, PInvoke.BLUETOOTH_GATT_FLAG_NONE);
        if ((hr.Failed && hr.Value != unchecked((int)EMoreData)) || actual == 0)
            return [];
        var buf = new BTH_LE_GATT_DESCRIPTOR[actual];
        ThrowIfFailed(PInvoke.BluetoothGATTGetDescriptors(
            h, ch, buf.AsSpan(), out actual, PInvoke.BLUETOOTH_GATT_FLAG_NONE), "BluetoothGATTGetDescriptors");
        return buf.AsSpan(0, actual).ToArray();
    }

    public static unsafe HRESULT WriteCharacteristic(
        SafeHandle h, BTH_LE_GATT_CHARACTERISTIC ch, byte[] packet, bool withoutResponse)
    {
        var size = BTH_LE_GATT_CHARACTERISTIC_VALUE.SizeOf(packet.Length);
        var mem = Marshal.AllocHGlobal(size);
        try
        {
            *(uint*)mem = (uint)packet.Length;
            var off = Marshal.OffsetOf<BTH_LE_GATT_CHARACTERISTIC_VALUE>("Data").ToInt64();
            Marshal.Copy(packet, 0, mem + (int)off, packet.Length);
            return PInvoke.BluetoothGATTSetCharacteristicValue(
                h, ch, (BTH_LE_GATT_CHARACTERISTIC_VALUE*)mem, 0,
                withoutResponse ? PInvoke.BLUETOOTH_GATT_FLAG_WRITE_WITHOUT_RESPONSE
                                : PInvoke.BLUETOOTH_GATT_FLAG_NONE);
        }
        finally
        {
            Marshal.FreeHGlobal(mem);
        }
    }
}
